#include <openssl/evp.h>
#include <pthread.h>
#include <string.h>
#include <stdlib.h>
#include <stdint.h>

static uint64_t load_be64(const unsigned char *p) {
    uint64_t v = 0;
    for (int i = 0; i < 8; i++) v = (v << 8) | p[i];
    return v;
}
static void store_be64(unsigned char *p, uint64_t v) {
    for (int i = 7; i >= 0; i--) { p[i] = v & 0xff; v >>= 8; }
}

static void gf_mul(uint64_t r[2], const uint64_t a[2], const uint64_t b[2]) {
    uint64_t z0 = 0, z1 = 0;
    uint64_t v0 = b[0], v1 = b[1];
    for (int i = 0; i < 64; i++) {
        if ((a[0] >> i) & 1) { z0 ^= v0; z1 ^= v1; }
        uint64_t carry = v1 >> 63;
        v1 = (v1 << 1) | (v0 >> 63);
        v0 <<= 1;
        if (carry) v0 ^= 0x87ULL;
    }
    for (int i = 0; i < 64; i++) {
        if ((a[1] >> i) & 1) { z0 ^= v0; z1 ^= v1; }
        uint64_t carry = v1 >> 63;
        v1 = (v1 << 1) | (v0 >> 63);
        v0 <<= 1;
        if (carry) v0 ^= 0x87ULL;
    }
    r[0] = z0; r[1] = z1;
}

static void gf_pow(uint64_t r[2], const uint64_t base[2], uint64_t e) {
    uint64_t result[2] = {1, 0};
    uint64_t b[2] = {base[0], base[1]};
    while (e) {
        if (e & 1) gf_mul(result, result, b);
        gf_mul(b, b, b);
        e >>= 1;
    }
    r[0] = result[0]; r[1] = result[1];
}

typedef struct {
    const unsigned char *key;
    int keylen;
    const unsigned char *nonce;
    const unsigned char *S;
    const unsigned char *pt;
    long long ptlen;
    unsigned char *ct;
    unsigned char *q;
    uint64_t start_block;
} chunk_arg;

static void *chunk_worker(void *argp) {
    chunk_arg *a = (chunk_arg*)argp;
    const EVP_CIPHER *ctr_cipher;
    if (a->keylen == 16) ctr_cipher = EVP_aes_128_ctr();
    else if (a->keylen == 24) ctr_cipher = EVP_aes_192_ctr();
    else ctr_cipher = EVP_aes_256_ctr();
    unsigned char iv[16];
    memcpy(iv, a->nonce, 12);
    uint32_t ctr = (uint32_t)(2 + a->start_block);
    iv[12] = (ctr >> 24) & 0xff;
    iv[13] = (ctr >> 16) & 0xff;
    iv[14] = (ctr >> 8) & 0xff;
    iv[15] = ctr & 0xff;
    EVP_CIPHER_CTX *cctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(cctx, ctr_cipher, NULL, a->key, iv);
    int outl = 0;
    EVP_EncryptUpdate(cctx, a->ct, &outl, a->pt, (int)a->ptlen);
    EVP_EncryptFinal_ex(cctx, a->ct + outl, &outl);
    EVP_CIPHER_CTX_free(cctx);

    const EVP_CIPHER *gcm_cipher;
    if (a->keylen == 16) gcm_cipher = EVP_aes_128_gcm();
    else if (a->keylen == 24) gcm_cipher = EVP_aes_192_gcm();
    else gcm_cipher = EVP_aes_256_gcm();
    EVP_CIPHER_CTX *gctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(gctx, gcm_cipher, NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(gctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(gctx, NULL, NULL, a->key, a->nonce);
    int len = 0;
    EVP_EncryptUpdate(gctx, NULL, &len, a->ct, (int)a->ptlen);
    int fin = 0;
    EVP_EncryptFinal_ex(gctx, NULL, &fin);
    unsigned char tag[16];
    EVP_CIPHER_CTX_ctrl(gctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
    EVP_CIPHER_CTX_free(gctx);

    unsigned char lenblock[16];
    memset(lenblock, 0, 16);
    store_be64(lenblock, (uint64_t)a->ptlen * 8);
    for (int i = 0; i < 16; i++) a->q[i] = tag[i] ^ a->S[i] ^ lenblock[i];
    return NULL;
}

static int gcm_encrypt_single(const unsigned char *key, int keylen,
                              const unsigned char *nonce, int noncelen,
                              const unsigned char *pt, long long ptlen,
                              const unsigned char *aad, long long aadlen,
                              unsigned char *ct, unsigned char *tag_out) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    const EVP_CIPHER *cipher;
    if (keylen == 16) cipher = EVP_aes_128_gcm();
    else if (keylen == 24) cipher = EVP_aes_192_gcm();
    else cipher = EVP_aes_256_gcm();
    int len = 0, outl = 0;
    EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, noncelen, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
    if (aadlen > 0) EVP_EncryptUpdate(ctx, NULL, &len, aad, (int)aadlen);
    if (ptlen > 0) EVP_EncryptUpdate(ctx, ct, &outl, pt, (int)ptlen);
    int fin = 0;
    EVP_EncryptFinal_ex(ctx, ct + outl, &fin);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag_out);
    EVP_CIPHER_CTX_free(ctx);
    return 0;
}

int gcm_encrypt_parallel(const unsigned char *key, int keylen,
                         const unsigned char *nonce, int noncelen,
                         const unsigned char *pt, long long ptlen,
                         const unsigned char *aad, long long aadlen,
                         unsigned char *ct, unsigned char *tag_out,
                         int nthreads) {
    if (noncelen != 12 || (ptlen % 16) != 0 || ptlen == 0) {
        return gcm_encrypt_single(key, keylen, nonce, noncelen, pt, ptlen, aad, aadlen, ct, tag_out);
    }
    const EVP_CIPHER *ecb;
    if (keylen == 16) ecb = EVP_aes_128_ecb();
    else if (keylen == 24) ecb = EVP_aes_192_ecb();
    else ecb = EVP_aes_256_ecb();
    unsigned char H[16], S[16], J0[16];
    EVP_CIPHER_CTX *ectx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ectx, ecb, NULL, key, NULL);
    int outl = 0;
    unsigned char zero[16] = {0};
    EVP_EncryptUpdate(ectx, H, &outl, zero, 16);
    memcpy(J0, nonce, 12);
    J0[12]=0; J0[13]=0; J0[14]=0; J0[15]=1;
    EVP_EncryptUpdate(ectx, S, &outl, J0, 16);
    EVP_CIPHER_CTX_free(ectx);

    long long M = ptlen / 16;
    long long base = M / nthreads;
    long long rem = M % nthreads;

    chunk_arg *args = malloc(sizeof(chunk_arg) * nthreads);
    pthread_t *threads = malloc(sizeof(pthread_t) * nthreads);
    unsigned char *q = malloc(16 * nthreads);

    long long start_block = 0;
    for (int t = 0; t < nthreads; t++) {
        long long blocks = base + (t < rem ? 1 : 0);
        long long chunk_bytes = blocks * 16;
        args[t].key = key; args[t].keylen = keylen;
        args[t].nonce = nonce; args[t].S = S;
        args[t].pt = pt + start_block * 16;
        args[t].ptlen = chunk_bytes;
        args[t].ct = ct + start_block * 16;
        args[t].q = q + 16 * t;
        args[t].start_block = start_block;
        pthread_create(&threads[t], NULL, chunk_worker, &args[t]);
        start_block += blocks;
    }
    for (int t = 0; t < nthreads; t++) pthread_join(threads[t], NULL);

    uint64_t Hx[2];
    Hx[1] = load_be64(H);
    Hx[0] = load_be64(H + 8);

    uint64_t ghash_aad[2] = {0, 0};
    long long naad_blocks = (aadlen + 15) / 16;
    for (long long i = 0; i < naad_blocks; i++) {
        unsigned char block[16];
        memset(block, 0, 16);
        long long off = i * 16;
        long long n = aadlen - off;
        if (n > 16) n = 16;
        if (n > 0) memcpy(block, aad + off, n);
        uint64_t bx[2];
        bx[1] = load_be64(block);
        bx[0] = load_be64(block + 8);
        ghash_aad[0] ^= bx[0]; ghash_aad[1] ^= bx[1];
        gf_mul(ghash_aad, ghash_aad, Hx);
    }

    uint64_t acc[2] = {0, 0};
    long long end_block = 0;
    for (int t = 0; t < nthreads; t++) {
        long long blocks = base + (t < rem ? 1 : 0);
        end_block += blocks;
        uint64_t qx[2];
        qx[1] = load_be64(q + 16 * t);
        qx[0] = load_be64(q + 16 * t + 8);
        uint64_t hp[2];
        gf_pow(hp, Hx, (uint64_t)(M - end_block));
        uint64_t term[2];
        gf_mul(term, qx, hp);
        acc[0] ^= term[0]; acc[1] ^= term[1];
    }
    uint64_t hp2[2];
    gf_pow(hp2, Hx, (uint64_t)(M + 1));
    uint64_t term2[2];
    gf_mul(term2, ghash_aad, hp2);
    acc[0] ^= term2[0]; acc[1] ^= term2[1];

    unsigned char lenblock[16];
    memset(lenblock, 0, 16);
    store_be64(lenblock, (uint64_t)aadlen * 8);
    store_be64(lenblock + 8, (uint64_t)ptlen * 8);
    uint64_t lbx[2];
    lbx[1] = load_be64(lenblock);
    lbx[0] = load_be64(lenblock + 8);
    uint64_t term3[2];
    gf_mul(term3, lbx, Hx);
    acc[0] ^= term3[0]; acc[1] ^= term3[1];

    unsigned char acc_bytes[16];
    store_be64(acc_bytes, acc[1]);
    store_be64(acc_bytes + 8, acc[0]);
    for (int i = 0; i < 16; i++) tag_out[i] = S[i] ^ acc_bytes[i];

    free(args); free(threads); free(q);
    return 0;
}
